DROP TABLE IF EXISTS `t_apply`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_apply`
(
    `id`                   int NOT NULL AUTO_INCREMENT,
    `name`                 varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '报名名称',
    `limit_end_time`       datetime                                                      DEFAULT NULL COMMENT '考试结束时间',
    `limit_start_time`     datetime                                                      DEFAULT NULL COMMENT '考试开始时间',
    `create_user`          int                                                           DEFAULT NULL COMMENT '创建人',
    `create_time`          datetime                                                      DEFAULT NULL COMMENT '创建时间',
    `deleted`              bit(1)                                                        DEFAULT NULL COMMENT '是否删除',
    `limited`              bit(1)                                                        DEFAULT NULL COMMENT '是否限制人数',
    `count`                int                                                           DEFAULT NULL COMMENT '限制报名人数量',
    `status`               int                                                           DEFAULT NULL COMMENT '报名状态：1.未发布  2.已发布  3.已关闭',
    `apply_end_time`       datetime                                                      DEFAULT NULL COMMENT '报名截止时间',
    `already_apply_count`  int                                                           DEFAULT NULL COMMENT '已报名人数',
    `apply_archive_id`     int                                                           DEFAULT NULL COMMENT '报名分类',
    `create_department_id` int                                                           DEFAULT NULL COMMENT '创建者部门id',
    `need_audit`           bit(1)                                                        DEFAULT NULL COMMENT '是否需要审核',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
