--
-- Table structure for table `t_exam_paper_answer`
--

DROP TABLE IF EXISTS `t_exam_paper_answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_exam_paper_answer`
(
    `id`                     bigint NOT NULL AUTO_INCREMENT,
    `exam_paper_id`          bigint                                                        DEFAULT NULL COMMENT '试卷Id',
    `paper_name`             varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '试卷名称',
    `paper_type`             int                                                           DEFAULT NULL COMMENT '试卷类型(人工组卷、抽题组卷、随机组卷)',
    `system_score`           int                                                           DEFAULT NULL COMMENT '系统判分',
    `user_score`             int                                                           DEFAULT NULL COMMENT '用户得分',
    `paper_score`            int                                                           DEFAULT NULL COMMENT '试卷总分',
    `question_correct`       int                                                           DEFAULT NULL COMMENT '正确题数',
    `question_count`         int                                                           DEFAULT NULL COMMENT '题目总数',
    `do_time`                int                                                           DEFAULT NULL COMMENT '耗时',
    `status`                 int                                                           DEFAULT NULL COMMENT '答卷状态',
    `create_user`            int                                                           DEFAULT NULL COMMENT '创建人',
    `create_time`            datetime                                                      DEFAULT NULL COMMENT '创建时间',
    `judge_user`             int                                                           DEFAULT NULL COMMENT '批改人',
    `answer_frame_id`        varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT '答卷内容Id',
    `exam_paper_archive_id`  int                                                           DEFAULT NULL COMMENT '试卷分类Id',
    `passed`                 bit(1)                                                        DEFAULT NULL COMMENT '是否合格',
    `pass_score`             int                                                           DEFAULT NULL COMMENT '合格分',
    `exam_paper_build_id`    bigint                                                        DEFAULT NULL COMMENT '试卷构建Id',
    `credential_template_id` int                                                           DEFAULT NULL COMMENT '证书模板',
    `limit_start_time`       datetime                                                      DEFAULT NULL COMMENT '考试开始时间',
    `limit_end_time`         datetime                                                      DEFAULT NULL COMMENT '考试结束时间',
    `create_department_id`   int                                                           DEFAULT NULL COMMENT '创建人部门',
    `deleted`                bit(1)                                                        DEFAULT NULL COMMENT '是否删除',
    `watch`                  bit(1)                                                        DEFAULT NULL COMMENT '是否允许查看答卷',
    `preview_file_path`      varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '答卷导出',
    `exam_paper_child_id`    bigint                                                        DEFAULT NULL COMMENT '子试卷id',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=165 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

