DROP TABLE IF EXISTS `t_exam_paper_answer_error`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_exam_paper_answer_error`
(
    `id`              bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `user_id`         int                                                           DEFAULT NULL COMMENT '用户ID',
    `vm_guid`         varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '虚拟机UUID',
    `vm_parent_id`    varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '虚拟机父ID',
    `exam_paper_id`   bigint                                                        DEFAULT NULL COMMENT '试卷ID',
    `answer_id`       bigint                                                        DEFAULT NULL COMMENT '答卷ID',
    `answer_frame_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT '答卷内容ID',
    `create_time`     datetime                                                      DEFAULT NULL COMMENT '创建时间',
    `update_time`     datetime                                                      DEFAULT NULL COMMENT '更新时间',
    `status`          int                                                           DEFAULT NULL COMMENT '状态 0待执行 1执行中 2执行完毕 3执行错误',
    `error_msg`       varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误信息',
    `deleted`         tinyint(1) DEFAULT NULL COMMENT '是否删除',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='试卷核验';
