DROP TABLE IF EXISTS `t_exam_paper_build`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_exam_paper_build`
(
    `id`                     bigint NOT NULL AUTO_INCREMENT,
    `exam_paper_archive_id`  int                                                           DEFAULT NULL COMMENT '试卷分类Id',
    `name`                   varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '试卷名称',
    `build_type`             int                                                           DEFAULT NULL COMMENT '1.人工组卷 2.抽题组卷 3.随机组卷',
    `pass_score`             int                                                           DEFAULT NULL COMMENT '考试合格分数',
    `score`                  int                                                           DEFAULT NULL COMMENT '试卷总分',
    `question_count`         int                                                           DEFAULT NULL COMMENT '题目总数',
    `suggest_time`           int                                                           DEFAULT NULL COMMENT '试卷时长',
    `limit_start_time`       datetime                                                      DEFAULT NULL COMMENT '考试开始时间',
    `limit_end_time`         datetime                                                      DEFAULT NULL COMMENT '考试结束时间',
    `publish_time`           datetime                                                      DEFAULT NULL COMMENT '发布时间',
    `build_status`           int                                                           DEFAULT NULL COMMENT '1.待发布  2.发布 ',
    `create_user`            int                                                           DEFAULT NULL COMMENT '创建人',
    `create_time`            datetime                                                      DEFAULT NULL COMMENT '创建时间',
    `deleted`                bit(1)                                                        DEFAULT NULL COMMENT '是否删除',
    `exam_paper_id`          bigint                                                        DEFAULT NULL COMMENT '试卷Id',
    `credential_template_id` int                                                           DEFAULT NULL COMMENT '证书模板',
    `range_type`             int                                                           DEFAULT NULL COMMENT '考试范围',
    `build_config`           json                                                          DEFAULT NULL COMMENT '构建试卷配置',
    `create_department_id`   int                                                           DEFAULT NULL,
    `vm_type`                varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '虚拟机类别',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
