-- Table structure for table `t_exam_paper_child`
--

DROP TABLE IF EXISTS `t_exam_paper_child`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_exam_paper_child`
(
    `id`                     bigint NOT NULL AUTO_INCREMENT,
    `name`                   varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '试卷名称',
    `paper_type`             int                                                           DEFAULT NULL COMMENT '试卷类型(人工组卷、抽题组卷、随机组卷)',
    `score`                  int                                                           DEFAULT NULL COMMENT '试卷分数',
    `question_count`         int                                                           DEFAULT NULL COMMENT '题目数量',
    `suggest_time`           int                                                           DEFAULT NULL COMMENT '考试时长',
    `limit_start_time`       datetime                                                      DEFAULT NULL COMMENT '考试开始时间',
    `limit_end_time`         datetime                                                      DEFAULT NULL COMMENT '考试结束时间',
    `paper_frame_id`         varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT '试卷结构信息表Id',
    `create_user`            int                                                           DEFAULT NULL COMMENT '创建人',
    `create_time`            datetime                                                      DEFAULT NULL COMMENT '创建时间',
    `deleted`                bit(1)                                                        DEFAULT NULL COMMENT '是否删除',
    `question_item_mess`     bit(1)                                                        DEFAULT NULL COMMENT '选项打乱',
    `question_mess`          bit(1)                                                        DEFAULT NULL COMMENT '题目打乱',
    `cheat`                  bit(1)                                                        DEFAULT NULL COMMENT '是否防作弊',
    `exam_paper_archive_id`  int                                                           DEFAULT NULL COMMENT '试卷分类',
    `pass_score`             int                                                           DEFAULT NULL COMMENT '合格分',
    `exam_paper_build_id`    bigint                                                        DEFAULT NULL COMMENT '试卷构建Id',
    `credential_template_id` int                                                           DEFAULT NULL COMMENT '证书模板',
    `capture`                bit(1)                                                        DEFAULT NULL COMMENT '考试抓拍',
    `create_department_id`   int                                                           DEFAULT NULL COMMENT '考试抓拍',
    `watch`                  bit(1)                                                        DEFAULT NULL COMMENT '是否允许查看答卷',
    `max_cheat_count`        int                                                           DEFAULT NULL COMMENT '最大作弊次数',
    `face_check`             bit(1)                                                        DEFAULT NULL COMMENT '人脸识别',
    `exam_paper_id`          bigint                                                        DEFAULT NULL COMMENT '父试卷id',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

