--
-- Table structure for table `t_menu`
--

DROP TABLE IF EXISTS `t_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_menu`
(
    `id`                   int NOT NULL AUTO_INCREMENT,
    `menu_name`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '菜单名称',
    `path`                 varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '页面路径',
    `meta_title`           varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '菜单名称',
    `meta_icon`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '菜单图标',
    `meta_no_cache`        bit(1)                                                        DEFAULT NULL COMMENT '是否缓存',
    `meta_affix`           bit(1)                                                        DEFAULT NULL,
    `meta_active_menu`     varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '激活菜单',
    `hidden`               bit(1)                                                        DEFAULT NULL COMMENT '是否隐藏',
    `component`            varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '视图路径',
    `parent_id`            int                                                           DEFAULT NULL COMMENT '父级Id',
    `deleted`              bit(1)                                                        DEFAULT NULL COMMENT '是否删除',
    `create_user`          int                                                           DEFAULT NULL COMMENT '创建人',
    `create_time`          datetime                                                      DEFAULT NULL COMMENT '创建时间',
    `level`                int                                                           DEFAULT NULL COMMENT '菜单层级',
    `always_show`          bit(1)                                                        DEFAULT NULL COMMENT '是否常显',
    `item_order`           int                                                           DEFAULT NULL COMMENT '排序',
    `name`                 varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '菜单名称',
    `create_department_id` int                                                           DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

