/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_menu_permission`
(
    `id`                   int NOT NULL AUTO_INCREMENT,
    `menu_id`              int                                                           DEFAULT NULL COMMENT '菜单Id',
    `identification`       varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '权限标识',
    `deleted`              bit(1)                                                        DEFAULT NULL COMMENT '是否删除',
    `name`                 varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '权限名称',
    `item_order`           int                                                           DEFAULT NULL COMMENT '排序',
    `create_user_id`       int                                                           DEFAULT NULL,
    `create_department_id` int                                                           DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=207 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
