--
-- Table structure for table `t_practice_build`
--

DROP TABLE IF EXISTS `t_practice_build`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_practice_build`
(
    `id`                     bigint NOT NULL AUTO_INCREMENT,
    `exam_paper_archive_id`  int                                                           DEFAULT NULL COMMENT '试卷分类Id',
    `name`                   varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '试卷名称',
    `build_type`             int                                                           DEFAULT NULL COMMENT '1.人工组卷 2.抽题组卷 3.随机组卷',
    `pass_score`             int                                                           DEFAULT NULL COMMENT '考试合格分数',
    `score`                  int                                                           DEFAULT NULL COMMENT '试卷总分',
    `question_count`         int                                                           DEFAULT NULL COMMENT '题目总数',
