DROP TABLE IF EXISTS `t_practice_exam_paper`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_practice_exam_paper`
(
    `id`                      bigint NOT NULL AUTO_INCREMENT,
    `name`                    varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '试卷名称',
    `paper_type`              int                                                           DEFAULT NULL COMMENT '试卷类型(人工组卷、抽题组卷、随机组卷)',
    `score`                   int                                                           DEFAULT NULL COMMENT '试卷分数',
    `question_count`          int                                                           DEFAULT NULL COMMENT '题目数量',
    `suggest_time`            int                                                           DEFAULT NULL COMMENT '考试时长',
    `limit_start_time`        datetime                                                      DEFAULT NULL COMMENT '考试开始时间',
    `limit_end_time`          datetime                                                      DEFAULT NULL COMMENT '考试结束时间',
    `practice_paper_frame_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci  DEFAULT NULL COMMENT '练习试卷结构信息表Id',
    `create_user`             int                                                           DEFAULT NULL COMMENT '创建人',
    `create_time`             datetime                                                      DEFAULT NULL COMMENT '创建时间',
    `deleted`                 bit(1)                                                        DEFAULT NULL COMMENT '是否删除',
    `exam_paper_archive_id`   int                                                           DEFAULT NULL COMMENT '试卷分类',
    `pass_score`              int                                                           DEFAULT NULL COMMENT '合格分',
    `practice_build_id`       bigint                                                        DEFAULT NULL COMMENT '练习构建Id',
    `create_department_id`    int                                                           DEFAULT NULL COMMENT '创建人部门',
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
