--
-- Table structure for table `t_question`
--

DROP TABLE IF EXISTS `t_question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_question`
(
    `id`                   bigint NOT NULL AUTO_INCREMENT,
    `question_type`        int                                                          DEFAULT NULL COMMENT '题型 ',
    `question_archive_id`  int                                                          DEFAULT NULL COMMENT '分类',
    `score`                int                                                          DEFAULT NULL COMMENT '分数',
    `difficult`            int                                                          DEFAULT NULL COMMENT '难度',
    `question_frame_id`    varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '题目内容Id',
    `create_user`          int                                                          DEFAULT NULL COMMENT '创建人',
    `status`               int                                                          DEFAULT NULL COMMENT '题目状态',
    `create_time`          datetime                                                     DEFAULT NULL COMMENT '创建时间',
    `deleted`              bit(1)                                                       DEFAULT NULL COMMENT '是否删除',
    `create_department_id` int                                                          DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=332 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

