INSERT INTO `t_question_json` VALUES ('075c7fbc-ab11-49e2-b769-653185680dee','{\"id\": \"075c7fbc-ab11-49e2-b769-653185680dee\", \"score\": 10, \"title\": \"在软件工程中，持续集成是指将开发者编写的代码合并到共享代码库中，并进行自动化构建和自动化测试的过程。这个说法正确吗？\", \"vmType\": null, \"analyze\": \"正确。持续集成是软件开发中的一种开发实践，主要目标是将开发者编写的代码频繁地合并到共享代码库中，并通过自动化构建和自动化测试的方式来确保代码的质量和稳定性。这样可以及早发现和解决代码集成时可能出现的问题，加快软件开发的速度和质量。\", \"command\": null, \"correct\": null, \"difficult\": 1, \"itemOrder\": null, \"correctKey\": 0, \"questionId\": 156, \"trickScore\": null, \"commandType\": null, \"questionType\": 3, \"correctPrefix\": \"A\", \"correctContent\": \"正确\", \"correctArrayKey\": null, \"questionArchiveId\": 7, \"questionItemFrames\": [{\"key\": 0, \"score\": null, \"prefix\": \"A\", \"content\": \"正确\", \"itemUuid\": null}, {\"key\": 1, \"score\": null, \"prefix\": \"B\", \"content\": \"错误\", \"itemUuid\": null}]}');
