INSERT INTO `t_question_json` VALUES ('0aa2f7a9-4d4b-4b47-9524-7210634bf257','{\"id\": \"0aa2f7a9-4d4b-4b47-9524-7210634bf257\", \"score\": 20, \"title\": \"Pod启动失败通过（）命令排查？\", \"analyze\": \"<p>kubectl describe pod：用于获取有关Pod的详细信息，包括任何错误或警告消息。</p><p>kubectl logs：用于查看Pod中容器的日志输出，可以帮助确定错误原因。</p><p>kubectl get pod：用于获取Pod的基本信息，包括状态和事件。</p><p>kubectl exec -it xxx bash：用于进入Pod中的某个容器的shell环境，以便进行进一步的排查和故障修复。<br/></p>\", \"correct\": null, \"difficult\": 1, \"itemOrder\": null, \"correctKey\": null, \"questionId\": 55, \"trickScore\": null, \"questionType\": 2, \"correctPrefix\": \"A B C D\", \"correctContent\": null, \"correctArrayKey\": [0, 1, 2, 3], \"questionArchiveId\": 2, \"questionItemFrames\": [{\"key\": 0, \"score\": null, \"prefix\": \"A\", \"content\": \"kubectl describe pod\", \"itemUuid\": null}, {\"key\": 1, \"score\": null, \"prefix\": \"B\", \"content\": \"kubectl logs\", \"itemUuid\": null}, {\"key\": 2, \"score\": null, \"prefix\": \"C\", \"content\": \"kubectl get pod\", \"itemUuid\": null}, {\"key\": 3, \"score\": null, \"prefix\": \"D\", \"content\": \"kubectl exec -it xxx bash\", \"itemUuid\": null}]}');
