INSERT INTO `t_question_json` VALUES ('4edc736b-d4a6-4b2b-a86e-98b3e4875deb','{\"id\": \"4edc736b-d4a6-4b2b-a86e-98b3e4875deb\", \"score\": 20, \"title\": \"在计算机网络中，OSI 参考模型的物理层主要负责（ ）。\", \"vmType\": null, \"analyze\": \"A 选项：建立、管理和终止应用程序之间的会话是会话层（OSI 模型的第五层）的主要职责。例如，在进行远程登录（如 Telnet）时，会话层负责建立和管理两个端点之间的会话连接，确保数据在会话期间能够正确地传输和交互。 B 选项：数据格式转换和数据加密通常是表示层（OSI 模型的第六层）的功能。比如在进行数据加密传输时，表示层会对要传输的数据进行加密算法处理，将原始数据转换为密文格式，在接收端再进行解密恢复为原始数据格式。 C 选项：物理层主要定义了物理介质（如双绞线、光纤、无线信号等）的电气、机械等特性，其主要任务是在物理介质上传输原始的比特流。例如，通过网线将计算机连接到网络时，物理层负责将计算机中的数字信号转换为适合在网线上传输的电信号或者光信号，从而实现比特流的传输。 D 选项：提供可靠的数据传输服务主要是传输层（OSI 模型的第四层）的功能。像 TCP 协议（传输控制协议）就属于传输层协议，它通过序列号、确认应答、重传机制等手段来确保数据能够可靠地从发送端传输到接收端。\", \"command\": null, \"correct\": null, \"difficult\": 1, \"itemOrder\": null, \"correctKey\": 2, \"questionId\": 324, \"trickScore\": null, \"commandType\": null, \"questionType\": 1, \"correctPrefix\": \"C\", \"correctContent\": null, \"correctArrayKey\": null, \"questionArchiveId\": 12, \"questionItemFrames\": [{\"key\": 0, \"score\": null, \"prefix\": \"A\", \"content\": \"建立、管理和终止应用程序之间的会话\", \"itemUuid\": null}, {\"key\": 1, \"score\": null, \"prefix\": \"B\", \"content\": \"数据格式转换和数据加密\", \"itemUuid\": null}, {\"key\": 2, \"score\": null, \"prefix\": \"C\", \"content\": \"在物理介质上传输比特流\", \"itemUuid\": null}, {\"key\": 3, \"score\": null, \"prefix\": \"D\", \"content\": \"提供可靠的数据传输服务\", \"itemUuid\": null}]}');
