INSERT INTO `t_question_json` VALUES ('e208e49f-c171-4a4b-aff7-c0840167190a','{\"id\": \"e208e49f-c171-4a4b-aff7-c0840167190a\", \"score\": 20, \"title\": \"以下支持正则表达式的命令是\", \"analyze\": \"grep：用于在文件中搜索匹配模式的行。支持基本正则表达式（BRE）和扩展正则表达式（ERE）。<br>sed：一种流编辑器，用于对文本进行编辑和转换。支持基本正则表达式（BRE）和扩展正则表达式（ERE）。<br>awk：一种文本处理工具，可以根据模式匹配和动作执行对文本进行操作。支持POSIX的基本和扩展正则表达式，以及与Perl兼容的正则表达式。<br>perl：一种高级编程语言，常用于文本处理和系统管理。支持Perl正则表达式，这是一种功能强大、灵活且复杂的正则表达式。<br></br></br></br></br>\", \"correct\": null, \"difficult\": 1, \"itemOrder\": null, \"correctKey\": null, \"questionId\": 49, \"trickScore\": null, \"questionType\": 2, \"correctPrefix\": \"A B C D\", \"correctContent\": null, \"correctArrayKey\": [0, 1, 2, 3], \"questionArchiveId\": 1, \"questionItemFrames\": [{\"key\": 0, \"score\": null, \"prefix\": \"A\", \"content\": \"grep\", \"itemUuid\": null}, {\"key\": 1, \"score\": null, \"prefix\": \"B\", \"content\": \"sed\", \"itemUuid\": null}, {\"key\": 2, \"score\": null, \"prefix\": \"C\", \"content\": \"awk\", \"itemUuid\": null}, {\"key\": 3, \"score\": null, \"prefix\": \"D\", \"content\": \"perl\", \"itemUuid\": null}]}');
INSERT INTO `t_question_json` VALUES ('e227f167-d020-4815-a71e-b861c25b14c9','{\"id\": \"e227f167-d020-4815-a71e-b861c25b14c9\", \"score\": 20, \"title\": \"以下属于RE中定位符的是\", \"analyze\": \"<p>^：匹配行的开始</p><p><span style=\\\"color: var(--el-text-color-regular);\\\">$：匹配行的结束</span></p><p>\\\\b：匹配单词边界，即单词和空格之间的位置</p><p>\\\\w：匹配单词字符，包括字母、数字和下划线<br/></p>\", \"correct\": null, \"difficult\": 1, \"itemOrder\": null, \"correctKey\": null, \"questionId\": 44, \"trickScore\": null, \"questionType\": 2, \"correctPrefix\": \"A B C D\", \"correctContent\": null, \"correctArrayKey\": [0, 1, 2, 3], \"questionArchiveId\": 1, \"questionItemFrames\": [{\"key\": 0, \"score\": null, \"prefix\": \"A\", \"content\": \"^\", \"itemUuid\": null}, {\"key\": 1, \"score\": null, \"prefix\": \"B\", \"content\": \"$\", \"itemUuid\": null}, {\"key\": 2, \"score\": null, \"prefix\": \"C\", \"content\": \"\\\\b\", \"itemUuid\": null}, {\"key\": 3, \"score\": null, \"prefix\": \"D\", \"content\": \"\\\\w\", \"itemUuid\": null}]}');
