INSERT INTO `t_question_json` VALUES ('f4851c26-4d19-43a4-894b-b77c08aba58e','{\"id\": \"f4851c26-4d19-43a4-894b-b77c08aba58e\", \"score\": 20, \"title\": \"以下属于awk支持的运算是\", \"analyze\": \"<ul><li>四则运算：包括加法、减法、乘法和除法等基本的数值运算。</li><li>比较运算：用于比较数值或字符串的大小关系，包括等于、不等于、大于、小于、大于等于和小于等于等比较操作。</li><li>比特码运算：awk不直接支持位运算或比特码运算，它主要用于对文本进行处理和操作。<br/></li><li>逻辑运算：包括与（AND）、或（OR）、非（NOT）等逻辑操作符，用于组合和判断条件。</li></ul><p><br/></p>\", \"correct\": null, \"difficult\": 1, \"itemOrder\": null, \"correctKey\": null, \"questionId\": 43, \"trickScore\": null, \"questionType\": 2, \"correctPrefix\": \"A B D\", \"correctContent\": null, \"correctArrayKey\": [0, 1, 3], \"questionArchiveId\": 1, \"questionItemFrames\": [{\"key\": 0, \"score\": null, \"prefix\": \"A\", \"content\": \"四则运算\", \"itemUuid\": null}, {\"key\": 1, \"score\": null, \"prefix\": \"B\", \"content\": \"比较运行\", \"itemUuid\": null}, {\"key\": 2, \"score\": null, \"prefix\": \"C\", \"content\": \"比特码运算\", \"itemUuid\": null}, {\"key\": 3, \"score\": null, \"prefix\": \"D\", \"content\": \"逻辑运算\", \"itemUuid\": null}]}');
