--
-- Table structure for table `t_train_exam_paper`
--

DROP TABLE IF EXISTS `t_train_exam_paper`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_train_exam_paper` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_paper_archive_id` int DEFAULT NULL COMMENT '试卷分类',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '试卷名称',
  `score` int DEFAULT NULL COMMENT '试卷分数',
  `question_count` int DEFAULT NULL COMMENT '题目数量',
  `suggest_time` int DEFAULT NULL COMMENT '考试时长',
  `paper_frame_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '试卷结构信息表Id',
  `question_item_mess` bit(1) DEFAULT NULL COMMENT '选项打乱',
  `question_mess` bit(1) DEFAULT NULL COMMENT '题目打乱',
  `cheat` bit(1) DEFAULT NULL COMMENT '是否防作弊',
  `max_cheat_count` int DEFAULT NULL,
  `create_user` int DEFAULT NULL COMMENT '创建人',
  `create_department_id` int DEFAULT NULL,
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `deleted` bit(1) DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

